#!/usr/bin/env bash
# Batch-size sweep of the deployed forest through PySpark (and ONNX for reference),
# to show that PySpark's edge cost is a fixed per-call overhead, not the trees.
#
# RUN ON JETSON #2, from the jetson/ directory, with the venv active:
#   ./scripts/sweep_batch_size.sh
# Each batch size writes its own JSON, so benchmark_same_forest.json is not overwritten.
# Pull results/batch_sweep_<tag>/ back to the Mac and commit it: board numbers
# cannot be regenerated by a re-run.
set -euo pipefail

cd "$(dirname "$0")/.."
TAG=${TAG:-$(date +%Y%m%d_%H%M)}
OUT=results/batch_sweep_$TAG
ENGINES=${ENGINES:-spark,onnx}
mkdir -p "$OUT"

# batch_size:samples:repeat  (replay CSV holds 10,000 rows; repeat tiles it so
# the largest batch still gives several batches for p50/p95)
if [ "${SKIP_SWEEP:-0}" != 1 ]; then
for spec in 10:1000:1 100:2000:1 1000:10000:1 10000:10000:5; do
  IFS=: read -r bs n rep <<<"$spec"
  echo "=== batch $bs, $n rows x $rep ==="
  python scripts/benchmark_same_forest.py --engines "$ENGINES" \
    --batch-size "$bs" --samples "$n" --repeat "$rep" \
    --out "$OUT/batch_${bs}.json"
done
fi

# ONNX finishes the runs above in under a second, too short for tegrastats
# (200 ms samples) to return energy. Tile the rows so each run lasts ~15-30 s.
for spec in 10:1000:270 100:2000:335 1000:10000:120 10000:10000:120; do
  IFS=: read -r bs n rep <<<"$spec"
  echo "=== onnx energy, batch $bs, $n rows x $rep ==="
  python scripts/benchmark_same_forest.py --engines onnx \
    --batch-size "$bs" --samples "$n" --repeat "$rep" \
    --out "$OUT/batch_${bs}_onnx_energy.json"
done

python - "$OUT" <<'EOF'
import glob, json, sys
rows = []
for f in sorted(glob.glob(f"{sys.argv[1]}/batch_*.json")):
    for r in json.load(open(f))["engines"]:
        rows.append(r)
rows.sort(key=lambda r: (r["engine"], r["batch_size"], r["samples"]))
keys = ["engine", "batch_size", "samples", "throughput_rps",
        "latency_batch_p50_ms", "latency_batch_p95_ms", "energy_active_per_inference_mj"]
with open(f"{sys.argv[1]}/summary.csv", "w") as fh:
    fh.write(",".join(keys) + "\n")
    for r in rows:
        fh.write(",".join(str(r.get(k)) for k in keys) + "\n")
print(open(f"{sys.argv[1]}/summary.csv").read())
EOF
